// Ported from the Node app's Sequelize model Attendance (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class AttendanceConfiguration : IEntityTypeConfiguration<Attendance>
{
    public void Configure(EntityTypeBuilder<Attendance> builder)
    {
        builder.ToTable("attendance", t =>
        {
            t.HasCheckConstraint("CK_attendance_status", "[status] IN (N'present', N'absent', N'late')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.Date).HasColumnName("date").HasColumnType("date");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired();
        builder.Property(e => e.ArrivalTime).HasColumnName("arrival_time").HasColumnType("nvarchar(5)").HasMaxLength(5);
        builder.Property(e => e.OutTime).HasColumnName("out_time").HasColumnType("nvarchar(5)").HasMaxLength(5);
        builder.Property(e => e.Note).HasColumnName("note").HasColumnType("nvarchar(120)").HasMaxLength(120);
        builder.Property(e => e.SavedAt).HasColumnName("saved_at").HasColumnType("datetime2");
        builder.HasIndex(e => new { e.StudentId, e.Date }).IsUnique().HasDatabaseName("uq_att");
        builder.HasOne(e => e.Student).WithMany(p => p.Attendances).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
